package com.example.application_service;import com.example.application_service.entity.ApplicationStatus;import com.example.application_service.exception.ApiException;import com.example.application_service.service.ApplicationRules;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class ApplicationRulesTest{private final ApplicationRules rules=new ApplicationRules();@Test void acceptsRecruitmentFlow(){assertThatCode(()->rules.transition(ApplicationStatus.APPLIED,ApplicationStatus.SCREENING)).doesNotThrowAnyException();assertThatCode(()->rules.transition(ApplicationStatus.SCREENING,ApplicationStatus.INTERVIEW)).doesNotThrowAnyException();assertThatCode(()->rules.transition(ApplicationStatus.INTERVIEW,ApplicationStatus.OFFER)).doesNotThrowAnyException();assertThatCode(()->rules.transition(ApplicationStatus.OFFER,ApplicationStatus.HIRED)).doesNotThrowAnyException();}@Test void rejectsSkippingAndTerminalTransitions(){assertThatThrownBy(()->rules.transition(ApplicationStatus.APPLIED,ApplicationStatus.HIRED)).isInstanceOf(ApiException.class).extracting("code").isEqualTo("INVALID_STATUS_TRANSITION");assertThatThrownBy(()->rules.transition(ApplicationStatus.REJECTED,ApplicationStatus.SCREENING)).isInstanceOf(ApiException.class);assertThatThrownBy(()->rules.transition(ApplicationStatus.HIRED,ApplicationStatus.REJECTED)).isInstanceOf(ApiException.class);}}
